using CustomCodeFramework.Messaging.Inbox;using CustomCodeFramework.Messaging.Outbox.Processing;using Dhole.Content.Persistence.DbContexts;using Microsoft.EntityFrameworkCore;namespace Dhole.Content.Worker.Outbox;internal sealed class InboxProcessor(ServiceDbContext db):IInboxProcessor{public async Task<InboxProcessingResult> CleanupAsync(TimeSpan olderThan,int batchSize,CancellationToken ct=default){var limitDate=DateTime.UtcNow.Subtract(olderThan);var messages=await db.InboxMessages.Where(x=>x.Status==InboxMessageStatus.Processed&&x.ProcessedAtUtc!=null&&x.ProcessedAtUtc<limitDate).OrderBy(x=>x.ProcessedAtUtc).Take(batchSize).ToListAsync(ct);if(messages.Count==0)return InboxProcessingResult.Empty;db.InboxMessages.RemoveRange(messages);await db.SaveChangesAsync(ct);var more=await db.InboxMessages.AnyAsync(x=>x.Status==InboxMessageStatus.Processed&&x.ProcessedAtUtc!=null&&x.ProcessedAtUtc<limitDate,ct);return new InboxProcessingResult(messages.Count,more);}}